import { faArrowDown, faArrowUp } from '@fortawesome/free-solid-svg-icons'
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome'

import { Labor, Penlab } from '@/type'

export function LaborTable({ data }: { data: Labor[] }) {
  if (data.length > 0) {
    return (
      <div className='border border-black'>
        {data.map((item: Labor, index) => (
          <div key={`labor-${index}`}>
            <div className='p-1 bg-gray-300'>
              <p className='text-xs'>{item?.tanggal ?? 'tanggal'}</p>
            </div>
            <div className=' p-1 bg-gray-400'>
              <h3 className='font-bold text-xs'>
                {item?.nama_kelompok ?? 'nama kelompok'}
              </h3>
            </div>
            <div>
              <div className='flex items-start justify-between'>
                <div className='w-full text-center border-r border-black'>
                  <div className='border-b border-black'>
                    <h3 className='font-medium py-1 text-xs'>
                      Item Pemeriksaan
                    </h3>
                  </div>
                  {item.penlab.map((item: Penlab, index) => (
                    <p
                      key={`labor-penlab-deskripsi-${index}`}
                      className='text-start  px-2 text-xs'
                    >
                      {item.pemeriksaan_deskripsi}
                    </p>
                  ))}
                </div>

                <div className='w-full text-center border-r border-black'>
                  <div className='border-b border-black'>
                    <h3 className='font-medium py-1 text-xs'>Hasil Analisa</h3>
                  </div>
                  {item.penlab.map((item, index) => (
                    <p
                      key={`labor-normal-${index}`}
                      className='text-center  px-2 text-xs'
                    >
                      {item.hasil ? (
                        item.hasil
                      ) : (
                        <div
                          style={{ minHeight: '1.5em', minWidth: '50px' }}
                        ></div>
                      )}
                    </p>
                  ))}
                </div>
                <div className='w-full border-r text-center border-black'>
                  <div className='border-b border-black'>
                    <h3 className='font-medium py-1 text-xs'>Penanda</h3>
                  </div>
                  {item.penlab.map((item, index) => (
                    <p
                      key={`labor-hasil-${index}`}
                      className='text-center  px-2 text-xs'
                    >
                      {item.kategori === 'BAWAH' ? (
                        <span>
                          <FontAwesomeIcon icon={faArrowDown} />
                        </span>
                      ) : item.kategori === 'ATAS' ? (
                        <span>
                          <FontAwesomeIcon icon={faArrowUp} />
                        </span>
                      ) : (
                        <div className='min-h-[1.5em] min-w-[50px] '></div>
                      )}
                    </p>
                  ))}
                </div>

                <div className='w-full border-r text-center border-black'>
                  <div className='border-b border-r-black border-black'>
                    <h3 className='font-medium py-1 text-xs '>Nilai Normal</h3>
                  </div>
                  {item.penlab.map((item, index) => (
                    <p
                      key={`labor-hasil-${index}`}
                      className='text-center   px-2 text-xs'
                    >
                      {item.normal ? (
                        item.normal
                      ) : (
                        <div
                          style={{ minHeight: '1.5em', minWidth: '50px' }}
                        ></div>
                      )}
                    </p>
                  ))}
                </div>

                <div className='w-full text-center border-black'>
                  <div className='border-b border-r border-black'>
                    <h3 className='font-medium py-1 text-xs'>
                      Keterangan / Satuan
                    </h3>
                  </div>
                  {item.penlab.map((item, index) => (
                    <p
                      key={`labor-hasil-${index}`}
                      className='text-center  px-2 text-xs'
                    >
                      {item.satuan ? (
                        item.satuan
                      ) : (
                        <div
                          style={{ minHeight: '1.5em', minWidth: '50px' }}
                        ></div>
                      )}
                    </p>
                  ))}
                </div>
              </div>
            </div>
          </div>
        ))}
      </div>
    )
  } else {
    return (
      <p className='text-xs text-center font-medium'>
        Tidak ada pemeriksaan labor
      </p>
    )
  }
}
