import { useState } from 'react'

import { useQuery } from '@tanstack/react-query'

import Error from '@/components/error'
import { LayoutBorderNo } from '@/components/layout_border_no'
import Loading from '@/components/loading'
import { SimpleColumn } from '@/components/simple-column'
import Text from '@/components/text'
import { Button } from '@/components/ui/button'
import EmtyDataPemberiInformasi from '@/features/pasien/pemberi-informasi/emty-data'
import FooterPemberian from '@/features/pasien/pemberi-informasi/footer-box'
import { getAllPemberiInformasi } from '@/services/pemberi-informasi'
import { constants } from '@/utils/constants'

interface PemberianInformasiProps {
  isReport?: boolean
  no?: string
  noreg?: string
}

export default function PemberianInformasi({
  isReport = false,
  no = '',
  noreg = '',
}: PemberianInformasiProps) {
  const [selected, setSelected] = useState(0)

  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.pemberiInformasi, noreg],
    queryFn: () => getAllPemberiInformasi(noreg),
    enabled: !!noreg,
  })

  const res = data?.response != null ? data.response : []

  if (isLoading) return <Loading />
  if (isError) return <Error />

  if (res == null || res.length == 0) return <EmtyDataPemberiInformasi />

  return (
    <>
      {res.map((item, index) => (
        <Button
          className='ml-2 mb-2'
          variant={selected == index ? 'default' : 'outline'}
          key={index}
          onClick={() => setSelected(index)}
        >
          {item.bagian}
        </Button>
      ))}
      <LayoutBorderNo no={no} isReport={isReport}>
        <div className='p-2'>
          <h1 className='text-center text-black font-semibold mb-4'>
            PEMBERIAN INFORMASI
          </h1>

          <div className='border border-black p-2'>
            <Text
              k='Dokter Pelaksana Tindakan'
              v={res[selected].dokter_pelaksana}
            />
            <Text k='Penerima Informasi' v={res[selected].penerima_informasi} />
            <Text
              k='Penerima Informasi/Pemberi Persetujuan *'
              v={res[selected].pemberi_persetujuan}
            />
            <div className='text-xs flex mt-2'>
              <SimpleColumn head name='NO' className='w-[50px]' />
              <SimpleColumn head name='JENIS INFORMASI' />
              <SimpleColumn head name='ISI INFORMASI' />
              <SimpleColumn
                head
                name='TANDAI (V)'
                isLast
                className='flex-[0.5]'
              />
            </div>
            <Row
              c0='1'
              c1='Diagnosis (WD & DD)'
              c2={res[selected].diagnosa.isi_informasi}
              c3={res[selected].diagnosa.tanda ? '✓' : ''}
            />
            <Row
              c0='2'
              c1='Dasar Diagnosis'
              c2={res[selected].dasar_diagnosis.isi_informasi}
              c3={res[selected].dasar_diagnosis.tanda ? '✓' : ''}
            />
            <Row
              c0='3'
              c1='Tindakan Kedokteran'
              c2={res[selected].tindakan_kedokteran.isi_informasi}
              c3={res[selected].tindakan_kedokteran.tanda ? '✓' : ''}
            />
            <Row
              c0='4'
              c1='Indikasi Tindakan'
              c2={res[selected].indikasi_tindakan.isi_informasi}
              c3={res[selected].indikasi_tindakan.tanda ? '✓' : ''}
            />
            <Row
              c0='5'
              c1='Tata Cara'
              c2={res[selected].tata_cara.isi_informasi}
              c3={res[selected].tata_cara.tanda ? '✓' : ''}
            />
            <Row
              c0='6'
              c1='Tujuan'
              c2={res[selected].tujuan.isi_informasi}
              c3={res[selected].tujuan.tanda ? '✓' : ''}
            />
            <Row
              c0='7'
              c1='Risiko'
              c2={res[selected].risiko.isi_informasi}
              c3={res[selected].risiko.tanda ? '✓' : ''}
            />
            <Row
              c0='8'
              c1='Komplikasi'
              c2={res[selected].komplikasi.isi_informasi}
              c3={res[selected].komplikasi.tanda ? '✓' : ''}
            />
            <Row
              c0='9'
              c1='Prognosis'
              c2={res[selected].prognosis.isi_informasi}
              c3={res[selected].prognosis.tanda ? '✓' : ''}
            />
            <Row
              c0='10'
              c1='Alternatif & Risiko'
              c2={res[selected].alternatif_risiko.isi_informasi}
              c3={res[selected].alternatif_risiko.tanda ? '✓' : ''}
            />
            <Row
              c0='11'
              c1='Hal lain yang akan dilakukan untuk menyelamatkan pasien'
              c2={res[selected].hal_lain.isi_informasi}
              c3={res[selected].hal_lain.tanda ? '✓' : ''}
            />
          </div>

          <FooterPemberian
            ttdPemberi={res[selected].ttd_pemberi.ttd}
            ttdPenerima={res[selected].ttd_penerima.ttd}
            pemberiInformasi={res[selected].ttd_penerima.nama}
            penerimaNama={res[selected].penerima_informasi}
          />
          <div className='h-[100px]' />
        </div>
      </LayoutBorderNo>
    </>
  )
}

const Row = ({
  c0,
  c1,
  c2,
  c3,
}: {
  c0?: string
  c1?: string
  c2?: string
  c3?: string
}) => {
  return (
    <div className='flex text-xs'>
      <SimpleColumn name={c0} className='w-[50px]' />
      <SimpleColumn name={c1} className='items-start flex-1' />
      <SimpleColumn name={c2} className='flex-1' />
      <SimpleColumn name={c3} className='flex-[0.5]' isLast />
    </div>
  )
}
