import { Laboratorium } from '@/services/resume_medis'

// import { Labor, Penlab } from '@/type'

export function LaborTableV2({ data }: { data: Laboratorium[] }) {
  if (data.length > 0) {
    return (
      <div className='border border-white'>
        {data.map((item: Laboratorium, index) => (
          <div key={`labor-${index}`}>
            <div className='p-1 bg-white-300'>
              <p className='text-xs'>
                {' '}
                {index + 1}. {item.pemeriksaan}
              </p>
            </div>
          </div>
        ))}
      </div>
    )
  } else {
    return (
      <p className='text-xs text-center font-medium'>
        Tidak ada pemeriksaan labor
      </p>
    )
  }
}
