import QRCode from 'react-qr-code'

import { useQuery } from '@tanstack/react-query'

import Error from '@/components/error'
import { LayoutBorderNo } from '@/components/layout_border_no'
import Loading from '@/components/loading'
import { getAsesmenDokterIgd } from '@/services/asesmen-dokter-igd'
import { constants } from '@/utils/constants'

import { RadiologiTable } from './radiologi-table'

interface PenmedikRadiologiProps {
  isReport?: boolean
  noreg?: string
  no?: string
}

export default function PenmedikRadiologi({
  isReport = true,
  noreg = '',
  no,
}: PenmedikRadiologiProps) {
  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.asesmenDokterIgd, noreg],
    queryFn: () => getAsesmenDokterIgd({ noreg: noreg! }),
    enabled: !!noreg,
  })

  const res = data != null ? data.response : null

  if (isLoading) return <Loading />
  if (isError) return <Error />

  return (
    <LayoutBorderNo isReport={isReport} no={no}>
      <div className='p-4'>
        <h3 className='font-bold text-center py-3'>PEMERIKSAAN RADIOLOGI</h3>

        <RadiologiTable data={res != null ? res.radiologi : []} />

        <div className='flex items-end justify-end my-8'>
          <div className='text-center flex flex-col items-center gap-4'>
            <p className='text-xs'>Dokter Penanggungjawab USG</p>
            <QRCode value='dokter' className='h-[50px] w-[50px]' />
            <p className='text-xs'>
              {res != null ? res.radiologi[0].dokter : '-'}
            </p>
          </div>
        </div>
      </div>
    </LayoutBorderNo>
  )
}
