import type { RegisterPasien, ReportGeneralConsentRanap, Response } from '@/type'

import { get, post } from './api'

const getGeneralConsentRanap = async (
    no_reg: string,
): Promise<Response<ReportGeneralConsentRanap>> => {
    const response = await get(`/v1/general-consent-ranap/${no_reg}/IGD001`)

    return response.data
}

const getRegisterPasien = async ({
    no_rm,
}: {
    no_rm: string
}): Promise<Response<RegisterPasien[]>> => {
    const response = await post(`/v1/register-pasien`, { no_rm: no_rm })

    return response.data
}

export { getGeneralConsentRanap, getRegisterPasien }
