import {  post } from '@/services/api';
import type { Response,  } from '@/type'


export interface TriasePonek {
    nama : string;
    skala_triase:       string;
    jam_pemeriksaan:    string;
    jam:                string;
    tanggal:            string;
    penyebab_cedera:    string;
    cara_masuk:         string;
    aseskep_asal_masuk: string;
    keluhan:            string;
    td:                 string;
    nadi:               string;
    pupil:              string;
    pernafasan:         string;
    suhu:               string;
    refleks:            string;
    spo2:               string;
    akral:              string;
    gcs_e:              string;
    gcs_v:              string;
    gcs_m:              string;
    insert_dttm:        string;
    hamil:              string;
    djj:                string;
    gravida:            string;
    para:               string;
    abortus:            string;
    hpht:               string;
    ttp:                string;
    his:                string;
}

// Converts JSON strings to/from your types
export class Convert {
    public static toTriasePonek(json: string): TriasePonek {
        return JSON.parse(json);
    }

    public static triasePonekToJson(value: TriasePonek): string {
        return JSON.stringify(value);
    }
}



const getTriasePONEK = async ({
  noreg,
}: {
  noreg: string
}): Promise<Response<TriasePonek>> => {
  const response = await post(`/v1/triase/get`, {
  "noreg" :noreg
})

  return response.data
}


export { getTriasePONEK}


