import { useQuery } from '@tanstack/react-query'

import EmptyPlaceholder from '@/components/empty-placeholder'
import Error from '@/components/error'
import { LayoutBorderNo } from '@/components/layout_border_no'
import Loading from '@/components/loading'
import Text from '@/components/text'
import { getPersetujuanRawatGabung } from '@/services/pemberi-informasi'
import { constants } from '@/utils/constants'

interface ReportPersetujuanRawatGabungProps {
  isReport?: boolean
  no?: string
  noreg?: string
}

export default function ReportPersetujuanRawatGabung({
  isReport = false,
  no = '',
  noreg = '',
}: ReportPersetujuanRawatGabungProps) {
  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.persetujuanRawatGabung, noreg],
    queryFn: () => getPersetujuanRawatGabung(noreg),
    enabled: !!noreg,
  })

  const res = data?.response != null ? data.response : null

  if (isLoading) return <Loading />
  if (isError) return <Error />

  if (res == null )
    return <EmptyPlaceholder message='Data tidak ditemukan.' />

  return (
    <LayoutBorderNo no={no} isReport={isReport}>
      <div className='p-2'>
        <h1 className='text-center text-black font-semibold mb-4'>
          SURAT PERSETUJUAN RAWAT GABUNG
        </h1>

        <p className='mb-2 text-sm'>
          Pematangsiantar, Tanggal: {res.tanggal} Pukul : {res.pukul} WIB
        </p>
        <h3 className='font-medium text-sm mb-2'>
          Kebijakan Rawat Gabung Ibu dan Bayi
        </h3>
        <div className='ml-4'>
          <div className='flex gap-2 text-xs mb-2'>
            <p>1. </p>
            <p>
              Setelah melahirkan, bayi akan diberikan perawatan awal, kemudian
              akan diantarkan <br /> oleh perawat yang bertugas ke kamar inap
              ibu.
            </p>
          </div>
          <div>
            <div className='flex gap-2 text-xs mb-2'>
              <p>2. </p>
              <p>
                Bayi yang dirawat gabung, mempunyai resiko yang untuk tertular
                penyakit yang <br /> berasal dari luar baik dari keluarga pasien
                maupun orang <br /> disekitar tempat inap pasien.
              </p>
            </div>
          </div>

          <div className='flex gap-2 text-xs mb-2'>
            <p>3. </p>
            <p>
              Perawat tidak bertugas mengambil bayi dari kamar inap pasien. Jika
              ada <br /> keperluan untuk memindahkan bayi ke ruang perawatan,
              maka ibu atau keluarga <br /> pasien yang bersangkutan yang
              membawa bayi ke ruang perawatan bayi, hal ini <br /> kami tujukan
              untuk menghindari resiko kehilangan bayi yang berada diluar <br />{' '}
              pengawasan pihak RS Tiara Kasih Sejati.
            </p>
          </div>
          <div className='flex gap-2 text-xs mb-2'>
            <p>4. </p>
            <p>
              Bayi yang dipindahkan ke ruangan perawatan dengan alasan ibu tidak
              dalam <br />
              keadaan sehat jasmani dan rohani (membutuhkan perawatan unit
              khusus), akan <br /> kami rawat di ruang perawatan bayi dengan
              ketentuan administrasi rumah sakit <br /> dan tidak bercampur
              dengan bayi sakit yang baru lahir.
            </p>
          </div>

          <p className='text-xs'>Saya yang bertanda tangan dibawah ini : </p>
          <Text k='Nama' kStyle='min-w-[100px]' v={res.nama} />
          <Text k='Alamat' kStyle='min-w-[100px]' v={res.alamat} />
          <Text k='No.KTP' kStyle='min-w-[100px]' v={res.no_ktp} />
          <p className='text-xs mt-2'>
            Menyatakan setuju untuk bertanggung jawab sepenuhnya terhadap segala{' '}
            <br />
            kemungkinan dan resiko yang terjadi sebagai akibat melakukan
            perawatan gabung ibu dan bayi. <br /> Demikian surat pernyataan
            persetujuan ini saya buat dengan penuh kesadaran dan <br /> tanpa
            paksaan
          </p>
        </div>
      </div>

      <div className='flex items-center justify-between'>
        <div className='p-2 mb-1 m-2'>
          <div className='text-center flex flex-col items-center gap-2'>
            <p className='text-xs font-semibold'>Yang membuat pernyataan</p>
            {res.yang_membuat_pernyataan.nama && (
              <img
                src={toImageUrl(res.yang_membuat_pernyataan.ttd)}
                alt='ttd'
                className='w-[50px] h-[50px]'
              />
            )}
            <p className='text-xs font-semibold'>
              ({res.yang_membuat_pernyataan.nama})
            </p>
          </div>
        </div>
        <div className='p-2 mb-1 m-2'>
          <div className='text-center flex flex-col items-center gap-2'>
            <p className='text-xs font-semibold'>Saksi</p>
            {res.saksi.nama && (
              <img
                src={toImageUrl(res.saksi.ttd)}
                alt='ttd'
                className='w-[50px] h-[50px]'
              />
            )}
            <p className='text-xs font-semibold'>({res.saksi.nama})</p>
          </div>
        </div>
        <div className='p-2 mb-1 m-2'>
          <div className='text-center flex flex-col items-center gap-2'>
            <p className='text-xs font-semibold'>
              Mengetahui
              <br />
              Dokter
            </p>
            {res.mengetahui_dokter.nama && (
              <img
                src={toImageUrl(res.mengetahui_dokter.ttd)}
                alt='ttd'
                className='w-[50px] h-[50px]'
              />
            )}
            <p className='text-xs font-semibold'>
              ({res.mengetahui_dokter.nama})
            </p>
          </div>
        </div>
      </div>
    </LayoutBorderNo>
  )
}

function toImageUrl(url: string) {
  const baseUrl = import.meta.env.VITE_BASE_API_URL_RME
  const image = baseUrl + '/app/images/rawat_gabung/'
  return image + url
}
