import { useEffect, useState } from 'react'
import QRCode from 'react-qr-code'

import { useQuery } from '@tanstack/react-query'

import { images } from '@/assets/images/images'
import Checkbox from '@/components/checkbox'
import Error from '@/components/error'
import { InformasiPasien } from '@/components/informasi_pasien'
import { LayoutBorderNo } from '@/components/layout_border_no'
import Loading from '@/components/loading'
import { SimpleColumn } from '@/components/simple-column'
import Text from '@/components/text'
import { DiagnosaTable } from '@/features/pasien-pulang/rekam-medis/components/diagnosa-table'
import { TextTitle } from '@/features/pasien-pulang/rekam-medis/components/text-title'
import { getAsesmenDokterIgd } from '@/services/asesmen-dokter-igd'
import { getTriase } from '@/services/triase'
import { usePasienStore } from '@/store/pasien.store'
import {
  Diagnosa,
  PemeriksaanFisikAsesmenDokterIgd,
  Triase,
  VitalSign,
} from '@/type'
import { constants } from '@/utils/constants'

interface AsesmenAwalMedisProps {
  isReport?: boolean
  noreg?: string
  no?: string
}

const initTriase: Triase = {
  abortus: '',
  djj: '',
  gravida: '',
  para: '',
  hpht: '',
  nama_pasien: '',
  tgl_lahir: '',
  no_rm: '',
  tgl_masuk: '',
  jam_pemeriksaan: '',
  jam_kedatangan: '',
  alasan_datang: '',
  penyebab_cedera: '',
  keluhan_utama: '',
  triase: {
    gcs: '',
    td: '',
    nadi: '',
    pupil: '',
    pernafasan: '',
    suhu: '',
    refleks: '',
    spo2: '',
    akral: '',
  },
  status_alergi: '',
  gangguan_perilaku: '',
  status_kehamilan: '',
  jalan_nafas: '',
  pernafasan: '',
  sirkulasi: '',
  kesadaran: '',
  nyeri: '',
  status_lendir: '',
  his: '',
  skor_nyeri: 0,
  petugas_triase: '',
  gambar_nyeri: [],
  ruangan: '',
  skala_triase: '',
}

export default function AsesmenAwalMedis({
  isReport = false,
  no,
  noreg,
}: AsesmenAwalMedisProps) {
  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.asesmenDokterIgd, noreg],
    queryFn: () => getAsesmenDokterIgd({ noreg: noreg! }),
    enabled: !!noreg,
  })

  const resTriase = useQuery({
    queryKey: [constants.queryKey.rekamMedis.triase, noreg],
    queryFn: () => getTriase({ noreg: noreg! }),
    enabled: !!noreg,
  })

  const res = data != null ? data.response : null
  const resultTriase =
    resTriase.data != null ? resTriase.data.response : initTriase

  const { pasien } = usePasienStore((state) => state)

  const [tempDiagnosa, setTempDiagnosa] = useState<Diagnosa[]>([])
  const [tempVitalSign, setTempVitalSign] = useState<VitalSign>({
    gcs: '',
    kesadaran: '',
    nadi: '',
    pernafasan: '',
    spo2: '',
    suhu: '',
    td: '',
  })
  const [tempPemeriksaanFisik, setTempPemeriksaanFisik] =
    useState<PemeriksaanFisikAsesmenDokterIgd>({
      alat_kelamin: '',
      anggota_gerak: '',
      dada: '',
      ginjal: '',
      hati: '',
      jantung: '',
      kekuatan_otot: '',
      kelenjar_getah_bening: '',
      kepala: '',
      kulit: '',
      leher: '',
      limpa: '',
      mata: '',
      mulut: '',
      paru: '',
      perut: '',
      relfeks: '',
      rt_vt: '',
      tht: '',
    })

  useEffect(() => {
    if (res) {
      setTempDiagnosa(res.diagnosa)
      setTempVitalSign(res.vital_sign)
      setTempPemeriksaanFisik(res.pemeriksaan_fisik)
    }
  }, [res])

  if (isLoading) return <Loading />
  if (isError) return <Error />
  if (res == null) return

  return (
    <>
      <LayoutBorderNo isReport={isReport} no={no}>
        {/* Content */}
        <div className='p-2 text-xs'>
          <h1 className='text-center text-black font-semibold mb-1'>
            ASESMEN AWAL MEDIS
          </h1>

          {/* Informasi Pasien */}
          {pasien != null && (
            <InformasiPasien
              nama={pasien.nama_pasien}
              noRM={pasien.no_rm}
              jenisKelamin={pasien.jenis_kelamin}
              tanggalLahir={pasien.tgl_lahir}
            />
          )}
          {/* Informasi Pasien */}

          {/* Tanggal dan Jam */}
          <div className='flex items-center gap-4 border border-black my-2 p-2'>
            <p className='flex-1'>
              Tanggal / Jam:{' '}
              {res != null ? (res.tanggal != '' ? res.tanggal : '-') : ''}
            </p>
          </div>
          {/* Tanggal dan Jam */}

          {/* Subyektif */}
          <div className='border border-black my-2 p-2'>
            <p className='flex-1 font-semibold'>SUBYEKTIF</p>
            <Text
              kStyle='min-w-[250px]'
              k='Keluhan Utama'
              v={res.keluhan_utama ?? '-'}
            />
            <Text
              kStyle='min-w-[250px]'
              k='Riwayat Penyakit Sekarang'
              v={res.penyakit_sekarang ?? '-'}
            />
            <Text
              kStyle='min-w-[250px]'
              k='Riwayat Penyakit Dahulu'
              v={res.penyakit_dahulu ?? '-'}
            />
            <Text
              kStyle='min-w-[250px]'
              k='Riwayat Penyakit Keluarga'
              v={res.penyakit_keluarga ?? '-'}
            />
            <Text
              kStyle='min-w-[250px]'
              k='Riwayat Penggunaan Obat'
              v={res.riwayat_penggunaan_obat ?? '-'}
            />
          </div>
          {/* Subyektif */}

          {/* Objektif */}
          <div className='border border-black my-2 p-2'>
            <div className='flex justify-between items-center'>
              <p className='flex-1 font-semibold'>OBJEKTIF</p>
            </div>
            <div className='flex justify-start items-start gap-[100px]'>
              <p>Tanda-Tanda Vital</p>
              <div className='flex items-start gap-4'>
                <div>
                  <div className='flex items-center gap-4'>
                    <p>GCS : {tempVitalSign.gcs ?? '-'}</p>
                  </div>
                  <Text
                    kStyle='min-w-[50px]'
                    k='TD'
                    v={tempVitalSign.td ?? '-'}
                  />
                  <Text
                    kStyle='min-w-[50px]'
                    k='Nadi'
                    v={tempVitalSign.nadi ?? '-'}
                  />
                  <Text
                    kStyle='min-w-[50px]'
                    k='Suhu'
                    v={tempVitalSign.suhu ?? '-'}
                  />
                </div>
                <div>
                  <Text
                    kStyle='min-w-[50px]'
                    k='Kesadaran'
                    v={tempVitalSign.kesadaran ?? '-'}
                  />
                  <Text
                    kStyle='min-w-[50px]'
                    k='Pernafasan'
                    v={tempVitalSign.pernafasan ?? '-'}
                  />
                  <Text
                    kStyle='min-w-[50px]'
                    k='SPO2'
                    v={tempVitalSign.spo2 ?? '-'}
                  />
                  <Text
                    kStyle='min-w-[50px]'
                    k='Refleks'
                    v={tempPemeriksaanFisik.relfeks ?? '-'}
                  />
                </div>
              </div>
            </div>
          </div>
          {/* Objektif */}

          {/* Pemeriksaan Fisik */}
          <div className='border border-black my-2 p-2'>
            <div className='flex items-center justify-between'>
              <p className='flex-1 font-semibold'>PEMERIKSAAN FISIK</p>
            </div>
            <div className='flex items-center gap-4'>
              <div className='flex-1'>
                <Text k='Kepala' v={tempPemeriksaanFisik.kepala ?? '-'} />
                <Text k='Mata' v={tempPemeriksaanFisik.mata ?? '-'} />
                <Text k='THT' v={tempPemeriksaanFisik.tht ?? '-'} />
                <Text k='Mulut' v={tempPemeriksaanFisik.mulut ?? '-'} />
                <Text k='Leher' v={tempPemeriksaanFisik.leher ?? '-'} />
                <Text k='Dada' v={tempPemeriksaanFisik.dada ?? '-'} />
                <Text k='Jantung' v={tempPemeriksaanFisik.jantung ?? '-'} />
                <Text k='Paru' v={tempPemeriksaanFisik.paru ?? '-'} />
                <Text k='Perut' v={tempPemeriksaanFisik.perut ?? '-'} />
                <Text k='Hati' v={tempPemeriksaanFisik.hati ?? '-'} />
              </div>
              <div className='flex-1'>
                <Text k='Limpa' v={tempPemeriksaanFisik.limpa ?? '-'} />
                <Text k='Ginjal' v={tempPemeriksaanFisik.ginjal ?? '-'} />
                <Text
                  k='Alat Kelamin'
                  v={tempPemeriksaanFisik.alat_kelamin ?? '-'}
                />
                <Text
                  k='Anggota Gerak'
                  v={tempPemeriksaanFisik.anggota_gerak ?? '-'}
                />
                <Text
                  k='Kekuatan Otot'
                  v={tempPemeriksaanFisik.kekuatan_otot ?? '-'}
                />
                <Text k='Kulit' v={tempPemeriksaanFisik.kulit ?? '-'} />
                <Text
                  k='Kelenjar Getah Bening'
                  v={tempPemeriksaanFisik.kelenjar_getah_bening ?? '-'}
                />
                <Text k='RT/VT' v={tempPemeriksaanFisik.rt_vt ?? '-'} />
              </div>
            </div>
            <div className='flex items-center justify-center'>
              <img
                src={res.image_lokalis}
                alt='anatomi tubuh'
                className='object-contain h-[300px]'
              />
              <img
                src={images.keterangan}
                alt='keterangan'
                className='object-contain h-[200px]'
              />
            </div>
          </div>
          {/* Pemeriksaan Fisik */}

          {/* Pemeriksaan Nyeri */}
          <div className='border border-black p-2 mb-1'>
            <p className='text-xs font-semibold mb-1'>Asesmen Nyeri</p>
            <div className='flex flex-col md:flex-row border border-black mb-1'>
              <div className='flex-1 border md:border-r-black p-2'>
                <Checkbox
                  title='Usia < 1 Tahun (NIPS)'
                  className='mb-1'
                  titleClassName='font-bold'
                />
                <div className='flex gap-4'>
                  <div>
                    <Checkbox title='0 (tidak nyeri)' className='mb-1' />
                    <Checkbox title='1 - 2 (ringan)' className='mb-1' />
                  </div>
                  <div>
                    <Checkbox title='3 - 4 (sedang)' className='mb-1' />
                    <Checkbox title='4 (berat)' className='mb-1' />
                  </div>
                </div>
              </div>
              <div className='flex-1 border md:border-r-black p-2'>
                <Checkbox
                  title='Usia < 6 Tahun (FLACCS)'
                  className='mb-1'
                  titleClassName='font-bold'
                />
                <div className='flex gap-4'>
                  <div>
                    <Checkbox title='0 (tidak nyeri)' className='mb-1' />
                    <Checkbox title='1 - 3 (ringan)' className='mb-1' />
                  </div>
                  <div>
                    <Checkbox title='4 - 6 (sedang)' className='mb-1' />
                    <Checkbox title='7 - 10 (berat)' className='mb-1' />
                  </div>
                </div>
              </div>
              <div className='flex-1 border p-2'>
                <Checkbox
                  title='Comfort Scale (pasien tidak sadar)'
                  className='mb-1'
                  titleClassName='font-bold'
                />
                <div className='flex gap-4'>
                  <div>
                    <Checkbox title='9-18 (nyeri kontrol)' className='mb-1' />
                    <Checkbox title='19 - 26 (ringan)' className='mb-1' />
                  </div>
                  <div>
                    <Checkbox title='27 - 35 (sedang)' className='mb-1' />
                    <Checkbox title='>35 (berat)' className='mb-1' />
                  </div>
                </div>
              </div>
            </div>
            <Checkbox
              title='Usia > 6 Tahun (Wong Baker Combined Numeric Rating Scale)'
              className='mb-4'
              titleClassName='font-bold'
            />

            <div className='flex items-center my-5'>
              <div className='flex flex-1 gap-4 justify-around'>
                <img
                  alt='skala nyeri icon'
                  src={images.skalaNyeri}
                  className='object-contain h-[180px] w-[600px]'
                />
              </div>
              <div className='flex-[0.3]'>
                {/* <Checkbox
                  title='0 (tidak nyeri)'
                  className='mb-2'
                  isChecked={resultTriase!.skor_nyeri == 0}
                /> */}
                <Checkbox
                  title='1 - 3 (ringan)'
                  className='mb-2'
                  isChecked={
                    resultTriase!.skor_nyeri >= 1 &&
                    resultTriase!.skor_nyeri <= 3
                  }
                />
                <Checkbox
                  title='4 - 6 (sedang)'
                  className='mb-2'
                  isChecked={
                    resultTriase!.skor_nyeri >= 4 &&
                    resultTriase!.skor_nyeri <= 6
                  }
                />
                <Checkbox
                  title='7 - 10 (berat)'
                  className='mb-2'
                  isChecked={
                    resultTriase!.skor_nyeri >= 7 &&
                    resultTriase!.skor_nyeri <= 10
                  }
                />
              </div>
            </div>
            <div>Umur {pasien?.umur} </div>

            <div className='flex-1 border md:border-r-black p-2 '>
              <Checkbox
                title='Usia < 6 Tahun (FLACCS)'
                className='mb-1'
                titleClassName='font-bold'
              />
              <div className='flex flex-1 mt-4'>
                <SimpleColumn
                  head
                  name='No.'
                  className='w-[50px] p-1'
                  className2='text-xs'
                />
                <SimpleColumn
                  head
                  name='Deskripsi'
                  className='p-1 flex-1'
                  className2='text-xs'
                  isLast
                />
                <SimpleColumn
                  head
                  name='Nilai'
                  className='p-1 flex-1'
                  className2='text-xs'
                  isLast
                />
              </div>
              {/* Wajah */}
              <div className='flex flex-1'>
                <SimpleColumn
                  name='1.'
                  className='w-[50px] p-1'
                  className2='text-xs'
                />
                <SimpleColumn
                  name='Wajah'
                  className='p-1 flex-1 items-start'
                  className2='text-xs'
                  isLast
                />
                <SimpleColumn
                  name={getWajahText(res.triase.wajah)}
                  className='p-1 flex-1 items-start'
                  className2='text-xs'
                  isLast
                />
              </div>

              {/* Kaki */}
              <div className='flex flex-1'>
                <SimpleColumn
                  name='2.'
                  className='w-[50px] p-1'
                  className2='text-xs'
                />
                <SimpleColumn
                  name='Kaki'
                  className='p-1 flex-1 items-start'
                  className2='text-xs'
                  isLast
                />
                <SimpleColumn
                  name={getKakiText(res.triase.kaki)}
                  className='p-1 flex-1 items-start'
                  className2='text-xs'
                  isLast
                />
              </div>

              {/* Aktifias */}
              <div className='flex flex-1'>
                <SimpleColumn
                  name='3.'
                  className='w-[50px] p-1 '
                  className2='text-xs'
                />
                <SimpleColumn
                  name='Aktifitas'
                  className='p-1 flex-1 items-start'
                  className2='text-xs'
                  isLast
                />
                <SimpleColumn
                  name={getAktifitasText(res.triase.aktifitas)}
                  className='p-1 flex-1 items-start'
                  className2='text-xs'
                  isLast
                />
              </div>

              {/* Menangis */}
              <div className='flex flex-1'>
                <SimpleColumn
                  name='4.'
                  className='w-[50px] p-1 '
                  className2='text-xs'
                />
                <SimpleColumn
                  name='Menangis'
                  className='p-1 flex-1 items-start'
                  className2='text-xs'
                  isLast
                />
                <SimpleColumn
                  name={getMenangisText(res.triase.menangis)}
                  className='p-1 flex-1 items-start'
                  className2='text-xs'
                  isLast
                />
              </div>

              {/* Bersuara */}
              <div className='flex flex-1'>
                <SimpleColumn
                  name='5.'
                  className='w-[50px] p-1 '
                  className2='text-xs'
                />
                <SimpleColumn
                  name='Bersuara'
                  className='p-1 flex-1 items-start '
                  className2='text-xs'
                />
                <SimpleColumn
                  name={getBersuaraText(res.triase.bersuara)}
                  className='p-1 flex-1 items-start'
                  className2='text-xs'
                  isLast
                />
              </div>
            </div>
          </div>

          {/* Asesmen */}
          <div className='border border-black my-2 p-2'>
            <div className='flex items-center justify-between'>
              <TextTitle title='Asesmen (Diagnosa Kerja)' />
            </div>
            <DiagnosaTable data={res != null ? tempDiagnosa : []} />
          </div>
          {/* Asesmen */}

          {/* PLANNING */}
          <div className='border border-black my-2 p-2'>
            <p className='flex-1 font-semibold'>
              PLANNING :{' '}
              <span className='text-xs font-normal'>
                Penatalaksanaan / Pengobatan / Rencana Tindakan / Konsultasi
              </span>
            </p>

            <p className='flex-1 my-2'>
              <p className='text-xs font-normal'>Terapi : {res?.terapi}</p>
              <p className='text-xs font-normal'>
                Konsul Ke : {res?.konsul_ke.split('-')[1]}
              </p>
            </p>
          </div>
          {/* PLANNING */}

          {/* PROGNOSA */}
          <div className='border border-black my-2 p-2'>
            <Text k='Prognosa' v={res.prognosis ?? '-'} />
          </div>
          {/* PROGNOSA */}
        </div>
        {/* Content */}

        {/* Dokter Yang Memeriksa */}
        <div className='p-2 mb-1 m-2'>
          <div className='flex flex-col gap-4 items-center text-center text-xs'>
            {res != null && res.dokter != '' && (
              <>
                <p className='text-sm'>Dokter Yang Memeriksa</p>
                <QRCode
                  value={res.dokter ?? '-'}
                  className='w-[100px] h-[100px]'
                />
                <p className=''>({res.dokter ?? '-'})</p>
              </>
            )}
          </div>
        </div>
        {/* Dokter Yang Memeriksa */}

        {/* Dialog */}
      </LayoutBorderNo>
    </>
  )
}

const getBersuaraText = (value: number) => {
  switch (value) {
    case 0:
      return 'Bersuara Normal / Tenang'

    case 1:
      return 'Tenang Bila Dipeluk, Digendong Atau Diajak Bicara'

    case 2:
      return 'Sulit Menenangkan'

    default:
      return '-'
  }
}

const getWajahText = (value: number) => {
  switch (value) {
    case 0:
      return 'Tersenyum / Tidak Ada Ekspresi Khusus'

    case 1:
      return 'Terkadang Menangis / Menarik Diri'

    case 2:
      return 'Sering Mengertakan Dagu Dan Mengatupkan Rahang'

    default:
      return '-'
  }
}

const getKakiText = (value: number) => {
  switch (value) {
    case 0:
      return 'Gerakan Normal / Relaksasi'

    case 1:
      return 'Tidak Tenang / Tegang'

    case 2:
      return 'Kaki Dibuatkan Menendang / Menarik Diri'

    default:
      return '-'
  }
}

const getAktifitasText = (value: number) => {
  switch (value) {
    case 0:
      return 'Tidur, Posisi Normal / Relaksasi'

    case 1:
      return 'Gerakan Menggeliat, Berguling, Kaku'

    case 2:
      return 'Melengkungkan Punggung / Kaku / Menghentak'

    default:
      return '-'
  }
}

const getMenangisText = (value: number) => {
  switch (value) {
    case 0:
      return 'Tidak Menangis (Bangun Tidur)'

    case 1:
      return 'Mengerang, Merengek-rengek'

    case 2:
      return 'Menangis Terus Menerus, Terhisak, Menjerit'

    default:
      return '-'
  }
}
