
import { cn } from '@/lib/utils'; // Pastikan path utils sesuai dengan project Anda

interface SignatureBoxProps {     // Teks di bagian atas (misal: "Petugas")
  signerName: string;      // Nama di dalam kurung (misal: "Budi Santoso")
  imagePath?: string;      // Nama file gambar dari API
  baseUrl?: string;        // Base URL API (VITE_BASE_API_URL_RME)
  className?: string;
}

export const SignatureBox = ({
  signerName,
  imagePath,
  baseUrl = import.meta.env.VITE_BASE_API_URL_RME,
  className
}: SignatureBoxProps) => {
  
  // Konstruksi URL lengkap untuk gambar
  const fullImageUrl = imagePath 
    ? `${baseUrl}/app/images/anastesia/${imagePath}` 
    : null;

  return (
    <div className={cn("text-center w-64 mx-auto", className)}>
      <div className=" h-32 w-full mb-2 flex items-center justify-center overflow-hidden bg-white">
        {imagePath ? (
          <img 
            src={fullImageUrl!} 
            alt={`Tanda tangan ${signerName}`} 
            className="max-h-full max-w-full object-contain"
            onError={(e) => {
              (e.target as HTMLImageElement).style.display = 'none';
            }}
          />
        ) : (
          <span className="text-gray-300 text-xs italic">Belum ditandatangani</span>
        )}
      </div>

      {/* Garis Bawah Nama */}
      <div className="border-b  w-full mb-2"></div>
    
      {/* Nama Penandatangan */}
      <p className="font-sans">( {signerName || '-'} )</p>
    </div>
  );
};