import type {
  RekamMedisLink,
  Response,
  RingkasanPerawatanPasienPulang,
} from '@/type'

import { get } from './api'
import {post, get as getV2 } from './api-2'
import { LembarSebabKematianResponse } from '@/models/lembar-sebab-kematian'
import { PersetujuanTindakanKedokteran } from '@/features/pasien/tindakan_kedokteran/tindakan_kedokteran_model'
import { ResumeMedis } from './resume_medis'

const getRekamMedisUrl = async (): Promise<Response<RekamMedisLink[]>> => {
  const response = await get(`/v1/rekam-medis`)

  return response.data
}

const getLembarSebabKematian = async (
  noreg: string,
): Promise<Response<LembarSebabKematianResponse>> => {
  const response = await post(`/v1/lembar-sebab-kematian`, { no_reg: noreg })

  return response.data
}


const getLaporanTindakanKedokteran = async (
  noreg: string,
): Promise<Response<PersetujuanTindakanKedokteran>> => {
  const response = await post(`/v1/laporan-persetujuan-tindakan-kedokteran`, { no_reg: noreg })

  return response.data
}


const getAllLaporanTindakanKedokteran = async (
  noreg: string,
): Promise<Response<PersetujuanTindakanKedokteran[]>> => {
  const response = await post(`/v1/all-laporan-persetujuan-tindakan-kedokteran`, { no_reg: noreg })

  return response.data
}


const getResumeMedis = async (
  no_reg: string,
): Promise<Response<RingkasanPerawatanPasienPulang>> => {
  const response = await get(`/v1/resume-medis/${no_reg}`)

  return response.data
}


const getResumeMedisV2 = async (
  no_reg: string,
): Promise<Response<ResumeMedis>> => {
  const response = await post(`/v1/laporan-resume-medis-ranap`, { no_reg: no_reg })

  return response.data
}

const getResumeMedisRanap = async (
  no_reg: string,
): Promise<Response<RingkasanPerawatanPasienPulang>> => {
  const response = await getV2(`/v1/resume-medis-ranap/${no_reg}`)

  return response.data
}

export { getRekamMedisUrl,getAllLaporanTindakanKedokteran, getResumeMedis,getResumeMedisRanap, getLembarSebabKematian , getLaporanTindakanKedokteran,getResumeMedisV2}
