
interface CheckboxListProps {
  options: string[];
  value: string[]; // daftar value yang sudah dipilih
}

const CheckboxList: React.FC<CheckboxListProps> = ({ options, value}) => {
 
  return (
    <div className="ml-10 flex-1">
      {options.map((option) => (
        <label key={option} className="flex items-center gap-4 bg-white 
              text-black
              cursor-pointer">
          <input
            type="checkbox"
            value={option}
            checked={value.includes(option)} 
          />
          {option}
        </label>
      ))}
    </div>
  );
};

export default CheckboxList;