import { useQuery } from '@tanstack/react-query'

import Error from '@/components/error'
import { LayoutBorderNo } from '@/components/layout_border_no'
import Loading from '@/components/loading'
import { SimpleColumn } from '@/components/simple-column'
import { SimpleTTD } from '@/components/simple-ttd'
import { formatTanggalIndoV2 } from '@/helper/date'
import { type CaseRegister, getCaseRegister } from '@/services/case-register'
import { constants } from '@/utils/constants'

interface CaseRegisterProps {
  isReport?: boolean
  noreg?: string
  no?: string
}

export function CaseRegister({
  isReport = true,
  noreg = '',
  no = '',
}: CaseRegisterProps) {
  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.caseRegister, noreg],
    queryFn: () => getCaseRegister({ no_reg: noreg }),
  })

  const result =
    data?.response != null ? data?.response : ({} as CaseRegister[])

  if (isLoading) return <Loading />
  if (isError) return <Error />

  return (
    <LayoutBorderNo no={no} isReport={isReport}>
      <div className='p-2'>
        <h1 className='text-center text-black font-semibold mb-4'>
          CASE REGISTER VISITE
        </h1>

        <div>
          {/* Header */}
          <div className='flex text-xs'>
            <SimpleColumn head name='No.' className={col.no} />
            <SimpleColumn head name='Tanggal' className={col.tanggal} />
            <SimpleColumn head name='Dokter' className={col.dokter} />
            <SimpleColumn head name='Visite' className={col.visite} />
            <SimpleColumn head name='Nama Pemeriksaan' className={col.nama} />
            <SimpleColumn head name='Paraf' className={col.paraf} isLast />
          </div>

          {/* Body */}
          {(result ?? []).length > 0 ? (
            result.map((item, index) => (
              <div className='flex text-xs' key={item.id}>
                <SimpleColumn
                  name={(index + 1).toString()}
                  className={col.no}
                />
                <SimpleColumn
                  name={formatTanggalIndoV2(item.tanggal)}
                  className={col.tanggal}
                />
                <SimpleColumn name={item.dokter} className={col.dokter} />
                <SimpleColumn name={item.visite} className={col.visite} />
                <SimpleColumn
                  name={item.nama_pemeriksaan}
                  className={col.nama}
                />
                <SimpleTTD
                  imageSrc={toImageUrl(item.paraf)}
                  isLast
                  name={item.dokter}
                  className={col.paraf}
                />
              </div>
            ))
          ) : (
            <div className='flex text-xs'>
              <SimpleColumn name='-' className={col.no} />
              <SimpleColumn name='-' className={col.tanggal} />
              <SimpleColumn name='-' className={col.dokter} />
              <SimpleColumn name='-' className={col.visite} />
              <SimpleColumn name='-' className={col.nama} />
              <SimpleColumn name='-' className={col.paraf} isLast />
            </div>
          )}
        </div>
      </div>
    </LayoutBorderNo>
  )
}

function toImageUrl(url: string) {
  const baseUrl = import.meta.env.VITE_BASE_API_URL_RME
  const image = baseUrl + '/app/images/case_register/'
  return image + url
}
const col = {
  no: 'w-[5%]  shrink-0',
  tanggal: 'w-[15%] shrink-0',
  dokter: 'w-[30%] shrink-0',
  visite: 'w-[15%] shrink-0',
  nama: 'w-[20%] shrink-0',
  paraf: 'w-[15%] shrink-0',
}
